package com.smartfood.wastemanagement.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.IOException; import java.nio.file.*; import java.util.Set; import java.util.UUID;
@Service public class UploadService { private final Path root; private static final Set<String> ALLOWED=Set.of("image/jpeg","image/png","image/webp","application/pdf"); public UploadService(@Value("${app.upload-dir:uploads}") String dir){root=Path.of(dir).toAbsolutePath().normalize();}
 public String save(MultipartFile file) throws IOException {if(file==null||file.isEmpty())return null;if(file.getSize()>5*1024*1024)throw new IllegalArgumentException("Each file must be 5 MB or smaller.");if(!ALLOWED.contains(file.getContentType()))throw new IllegalArgumentException("Only JPG, PNG, WEBP and PDF files are allowed.");Files.createDirectories(root);String original=file.getOriginalFilename()==null?"file":file.getOriginalFilename();String ext=original.contains(".")?original.substring(original.lastIndexOf('.')).replaceAll("[^A-Za-z0-9.]",""):"";String name=UUID.randomUUID()+ext;Files.copy(file.getInputStream(),root.resolve(name),StandardCopyOption.REPLACE_EXISTING);return name;}
}